package com.example.starter.firmware.api;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 创建多跳回退计划请求。针对一张已结束投放单，给出目标旧版本与完整设备集合，
 * 系统按各设备成功投放历史构造1～5跳的连续反向路径；设备集合换序视为同一请求。
 */
public record CreateRollbackPlanRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String planKey,
        @NotNull Long sourceReleaseId,
        @NotBlank @Size(max = 64) String targetVersion,
        @NotEmpty List<@NotBlank @Size(max = 64) String> devices,
        @Min(2) @Max(100) Integer sampleFloor,
        @Min(1) @Max(100) Integer failureThresholdPercent) {

    public static final int DEFAULT_SAMPLE_FLOOR = 2;
    public static final int DEFAULT_FAILURE_THRESHOLD_PERCENT = 100;

    public int effectiveSampleFloor() {
        return sampleFloor == null ? DEFAULT_SAMPLE_FLOOR : sampleFloor;
    }

    public int effectiveFailureThresholdPercent() {
        return failureThresholdPercent == null ? DEFAULT_FAILURE_THRESHOLD_PERCENT : failureThresholdPercent;
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.RollbackPlan;

/**
 * 回退计划视图。
 */
public record RollbackPlanView(long planId, String planKey, long sourceReleaseId, String targetVersion,
                               String status, int currentHop, int maxHop,
                               int sampleFloor, int failureThresholdPercent,
                               int currentRound, int roundSuccess, int roundFailed) {

    public static RollbackPlanView of(RollbackPlan plan) {
        return new RollbackPlanView(plan.id(), plan.planKey(), plan.sourceReleaseId(), plan.targetVersion(),
                plan.status().name(), plan.currentHop(), plan.maxHop(),
                plan.sampleFloor(), plan.failureThresholdPercent(),
                plan.currentRound(), plan.roundSuccess(), plan.roundFailed());
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.RollbackTask;

/**
 * 回退波次任务视图，expectedVersion/toVersion/sourceReleaseId 为派发时冻结值。
 */
public record RollbackTaskView(long taskId, long planId, int hopIndex, int round, String deviceId,
                               String status, String expectedVersion, String toVersion,
                               long sourceReleaseId, String firstResult) {

    public static RollbackTaskView of(RollbackTask task) {
        return new RollbackTaskView(task.id(), task.planId(), task.hopIndex(), task.round(), task.deviceId(),
                task.status().name(), task.expectedVersion(), task.toVersion(), task.sourceReleaseId(),
                task.firstResult() == null ? null : task.firstResult().name());
    }
}

package com.example.starter.firmware.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 回退波次派发请求：设备主动拉取当前跳当前轮次任务；PAUSED 后及后续跳停止派发。
 */
public record DispatchRollbackRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String deviceId) {
}

package com.example.starter.firmware.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 回退计划人工恢复请求：仅 PAUSED 可恢复，生成当前跳新 round 且只包含该跳未成功设备。
 */
public record ResumeRollbackPlanRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 256) String reason) {
}

