        assertThat(rel1).isNotEqualTo(relA);
        assertThat(relB).isPositive();
        assertThat(deviceService.get("d1").currentVersion()).isEqualTo("v3");
        assertThat(deviceService.get("d2").currentVersion()).isEqualTo("v3");
