    private long chainSourceRelease;

    /**
     * 直接以 H2 数据构造 n 代连续升级成功历史：v0→v1→...→vn，全部发布单 CANCELLED。
     */
    private void buildLongChainDevice(String deviceId, int generations) {
        jdbc.update("INSERT INTO device (device_id, model, current_version, bucket_no) VALUES (?, 'mc', ?, 1)",
                deviceId, "v" + generations);
        long prevTask = 0;
        for (int i = 0; i < generations; i++) {
            long releaseId;
            Long key = jdbc.queryForObject(
                    "SELECT COALESCE(MAX(id),0)+1 FROM release_order", Long.class);
            releaseId = key;
            jdbc.update("INSERT INTO release_order (id, version, model, from_version, to_version, ratio, status,"
                            + " sample_floor, failure_threshold_percent, monitor_round, active_model)"
                            + " VALUES (?, 1, 'mc', ?, ?, 100, 'CANCELLED', 2, 100, 1, NULL)",
                    releaseId, "v" + i, "v" + (i + 1));
            Long taskKey = jdbc.queryForObject("SELECT COALESCE(MAX(id),0)+1 FROM rollout_task", Long.class);
            jdbc.update("INSERT INTO rollout_task (id, release_id, device_id, status, first_result)"
                    + " VALUES (?, ?, ?, 'SUCCESS', 'SUCCESS')", taskKey, releaseId, deviceId);
            prevTask = taskKey;
        }
        chainSourceRelease = jdbc.queryForObject(
                "SELECT release_id FROM rollout_task WHERE id = ?", Long.class, prevTask);
    }

